package com.pcguard.service;
import com.pcguard.dto.AgentDtos.*; import com.pcguard.entity.*; import com.pcguard.repository.*; import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@Service public class MonitoringService {
 private final ComputerRepository computers; private final TelemetryRepository telemetry; private final HeartbeatRepository heartbeats; private final FaultRepository faults; private final ReportRepository reports; private final List<SseEmitter> streams=new java.util.concurrent.CopyOnWriteArrayList<>();
 @Value("${pcguard.threshold.cpu-warning}") double cpuWarning; @Value("${pcguard.threshold.cpu-critical}") double cpuCritical; @Value("${pcguard.threshold.ram-warning}") double ramWarning; @Value("${pcguard.threshold.ram-critical}") double ramCritical; @Value("${pcguard.threshold.storage-warning}") double storageWarning; @Value("${pcguard.threshold.storage-critical}") double storageCritical;
 public MonitoringService(ComputerRepository c,TelemetryRepository t,HeartbeatRepository h,FaultRepository f,ReportRepository r){computers=c;telemetry=t;heartbeats=h;faults=f;reports=r;}
 @Transactional public Computer register(Registration r){Computer c=computers.findByAgentId(r.agentId()).orElseGet(Computer::new); c.agentId=r.agentId();c.hostname=r.hostname();c.operatingSystem=r.os();c.osVersion=r.osVersion();c.architecture=r.architecture();c.agentVersion=r.agentVersion(); if(c.registeredAt==null)c.registeredAt=Instant.now();c.lastSeen=Instant.now();c.status=Computer.Status.ONLINE;return computers.save(c);}
 @Transactional public void heartbeat(String agentId,HeartbeatRequest r,String ip){Computer c=findAgent(agentId);Instant now=r.timestamp()==null?Instant.now():r.timestamp();c.lastSeen=now;c.agentVersion=r.agentVersion();c.ipAddress=ip;c.status=Computer.Status.ONLINE;Heartbeat h=new Heartbeat();h.computer=c;h.timestamp=now;h.agentVersion=r.agentVersion();h.status=r.status()==null?"RUNNING":r.status();h.ipAddress=ip;heartbeats.save(h);broadcast("heartbeat",Map.of("computerId",c.id,"status",c.status,"lastSeen",now.toString()));}
 @Transactional public Telemetry submit(String agentId,TelemetryRequest r){Computer c=findAgent(agentId); Telemetry t=new Telemetry();t.computer=c;t.timestamp=r.timestamp()==null?Instant.now():r.timestamp(); Map<String,Object> cpu=n(r.cpu()),mem=n(r.memory()),temp=n(r.temperature()); t.cpuUsage=d(cpu,"usagePercent","usage");t.cpuTemperature=d(temp,"cpuTemperatureCelsius","temperature");t.ramTotal=l(mem,"totalBytes","total");t.ramUsed=l(mem,"usedBytes","used");t.ramAvailable=l(mem,"availableBytes","available");t.ramUsage=d(mem,"usagePercent","usage"); List<Map<String,Object>> stores=r.storage()==null?List.of():r.storage(); for(Map<String,Object>s:stores){t.storageTotal=add(t.storageTotal,l(s,"totalBytes","total"));t.storageUsed=add(t.storageUsed,l(s,"usedBytes","used"));t.storageFree=add(t.storageFree,l(s,"freeBytes","free"));} if(t.storageTotal!=null&&t.storageTotal>0)t.storageUsage=t.storageUsed*100d/t.storageTotal; List<Map<String,Object>> nets=r.network()==null?List.of():r.network();if(!nets.isEmpty()){t.networkStatus=Boolean.TRUE.equals(nets.getFirst().get("up"))?"CONNECTED":"DISCONNECTED";for(Map<String,Object>x:nets){t.networkDownload=add(t.networkDownload,l(x,"bytesReceived"));t.networkUpload=add(t.networkUpload,l(x,"bytesSent"));}}t.uptime=r.uptime(); telemetry.save(t);c.lastSeen=Instant.now();c.status=severityStatus(t); evaluate(c,"CPU_HIGH",t.cpuUsage,cpuWarning,cpuCritical,"CPU usage");evaluate(c,"RAM_HIGH",t.ramUsage,ramWarning,ramCritical,"RAM usage");evaluate(c,"STORAGE_HIGH",t.storageUsage,storageWarning,storageCritical,"Storage usage");broadcast("telemetry",view(t));return t; }
 private Computer findAgent(String id){return computers.findByAgentId(id).orElseThrow(()->new NoSuchElementException("Unknown agent: "+id));} private static Map<String,Object> n(Map<String,Object>x){return x==null?Map.of():x;} private static Double d(Map<String,Object>x,String...keys){for(String k:keys){Object v=x.get(k);if(v instanceof Number z)return z.doubleValue();}return null;} private static Long l(Map<String,Object>x,String...keys){for(String k:keys){Object v=x.get(k);if(v instanceof Number z)return z.longValue();}return null;} private static Long add(Long a,Long b){return b==null?a:a==null?b:a+b;}
 private Computer.Status severityStatus(Telemetry t){if((t.cpuUsage!=null&&t.cpuUsage>=cpuCritical)||(t.ramUsage!=null&&t.ramUsage>=ramCritical)||(t.storageUsage!=null&&t.storageUsage>=storageCritical))return Computer.Status.CRITICAL;if((t.cpuUsage!=null&&t.cpuUsage>=cpuWarning)||(t.ramUsage!=null&&t.ramUsage>=ramWarning)||(t.storageUsage!=null&&t.storageUsage>=storageWarning))return Computer.Status.WARNING;return Computer.Status.ONLINE;}
 private void evaluate(Computer c,String type,Double value,double warning,double critical,String metric){if(value==null)return;double threshold=value>=critical?critical:warning;Fault.Severity level=value>=critical?Fault.Severity.CRITICAL:value>=warning?Fault.Severity.WARNING:null;Optional<Fault> existing=faults.findByComputerIdAndTypeAndStatus(c.id,type,Fault.Status.ACTIVE);if(level==null){existing.ifPresent(f->{f.status=Fault.Status.RESOLVED;f.resolvedAt=Instant.now();reports.save(report(c,"SYSTEM_HEALTH",metric+" recovered",f.severity,"Metric returned below threshold"));});return;} Fault f=existing.orElseGet(Fault::new);boolean newFault=f.id==null;f.computer=c;f.type=type;f.severity=level;f.message=metric+" exceeded configured "+level.name().toLowerCase()+" threshold";f.metric=metric;f.currentValue=value;f.threshold=threshold;if(newFault){f.detectedAt=Instant.now();f.status=Fault.Status.ACTIVE;}faults.save(f);if(newFault)reports.save(report(c,level==Fault.Severity.CRITICAL?"RESOURCE_CRITICAL":"RESOURCE_WARNING",f.message,level,f.message));}
 private Report report(Computer c,String type,String title,Fault.Severity severity,String desc){Report r=new Report();r.computer=c;r.reportType=type;r.title=title;r.description=desc;r.severity=severity;r.createdAt=Instant.now();r.status="OPEN";r.generatedBy="fault-detector";return r;}
 public List<Computer> computers(){return computers.findAll();} public Computer computer(Long id){return computers.findById(id).orElseThrow(()->new NoSuchElementException("Computer not found"));} @Transactional public void deleteComputer(Long id){Computer c=computer(id);telemetry.deleteByComputerId(id);heartbeats.deleteByComputerId(id);faults.deleteByComputerId(id);reports.deleteByComputerId(id);computers.delete(c);} public List<Telemetry> telemetry(Long id){computer(id);return telemetry.findTop100ByComputerIdOrderByTimestampDesc(id);} public List<Fault> faults(Long id){return id==null?faults.findAll():faults.findByComputerIdOrderByDetectedAtDesc(id);} public List<Report> reports(Long id){return id==null?reports.findAllByOrderByCreatedAtDesc():reports.findByComputerIdOrderByCreatedAtDesc(id);} public Map<String,Object> summary(){return Map.of("totalComputers",computers.count(),"online",computers.countByStatus(Computer.Status.ONLINE),"offline",computers.countByStatus(Computer.Status.OFFLINE),"warning",computers.countByStatus(Computer.Status.WARNING),"critical",computers.countByStatus(Computer.Status.CRITICAL),"activeFaults",faults.countByStatus(Fault.Status.ACTIVE));}
 public SseEmitter stream(){SseEmitter e=new SseEmitter(0L);streams.add(e);e.onCompletion(()->streams.remove(e));e.onTimeout(()->streams.remove(e));return e;} private void broadcast(String name,Object payload){for(SseEmitter e:streams)try{e.send(SseEmitter.event().name(name).data(payload));}catch(Exception x){streams.remove(e);}}
 public Map<String,Object> view(Telemetry t){return Map.of("computerId",t.computer.id,"timestamp",t.timestamp.toString(),"cpuUsage",Optional.ofNullable(t.cpuUsage).orElse(0d),"ramUsage",Optional.ofNullable(t.ramUsage).orElse(0d),"storageUsage",Optional.ofNullable(t.storageUsage).orElse(0d),"status",t.computer.status.name());}
}
